IF DB_ID('OmnichannelElectronics') IS NULL CREATE DATABASE OmnichannelElectronics;
GO
USE OmnichannelElectronics;
GO
DROP TABLE IF EXISTS dbo.SalesOrders;
DROP TABLE IF EXISTS dbo.Customers;
DROP TABLE IF EXISTS dbo.Products;
GO
CREATE TABLE dbo.Customers(
 CustomerID INT PRIMARY KEY,
 CustomerName VARCHAR(120),
 City VARCHAR(60),
 Region VARCHAR(60),
 Segment VARCHAR(30)
);
CREATE TABLE dbo.Products(
 ProductID INT PRIMARY KEY,
 ProductName VARCHAR(120),
 Category VARCHAR(60),
 ListPrice DECIMAL(12,2)
);
CREATE TABLE dbo.SalesOrders(
 OrderID INT PRIMARY KEY,
 OrderDate DATE,
 CustomerID INT,
 ProductID INT,
 Region VARCHAR(60),
 Quantity INT,
 UnitPrice DECIMAL(12,2),
 SalesAmount DECIMAL(14,2),
 SalesRepID INT,
 SalesChannel VARCHAR(30),
 PaymentStatus VARCHAR(20),
 CONSTRAINT FK_Sales_Customer FOREIGN KEY(CustomerID) REFERENCES dbo.Customers(CustomerID),
 CONSTRAINT FK_Sales_Product FOREIGN KEY(ProductID) REFERENCES dbo.Products(ProductID)
);
GO
